using System.ComponentModel.Composition;

[ExportMetadataAttribute(identifierStr(TableName), tableStr(LogisticsLocation))]
[ExportMetadataAttribute(identifierStr(EntityName), dataentityviewstr(METSmmCustContactPersonV2Entity))]
[ExportAttribute(identifierstr(Dynamics.AX.Application.IBusinessEventsTableToEntityRecordIdSelector))]
internal final class METSmmContactPersonV2EntityRecordIdSelectorLogisticsLocation implements IBusinessEventsTableToEntityRecordIdSelector
{
}

Method.Source:
[Hookable(false)]
public List getEntityRecordIdsImpactedByTableChange(BusinessEventsDefinition _eventDefinition, BusinessEventsActions _changeType, RecId _changedRecordId)
{
    List impactedRecIds = new List(Types::Int64);

    ContactPerson contactPerson;
    DirPartyTable dirPartyTable;

    // Only the primary address is mapped on the contact person entity.
    while select RecId from contactPerson
        exists join dirPartyTable
            where dirPartyTable.PrimaryAddressLocation == _changedRecordId
                && dirPartyTable.RecId == contactPerson.Party
    {
        impactedRecIds.addEnd(contactPerson.RecId);
    }

    return impactedRecIds;
}
